"""🎯 Demo Prep — generated by the backend from the CV / JD / project documents selected for this meeting."""
from __future__ import annotations

from datetime import datetime
from html import escape

from PySide6.QtCore import QObject, Qt, QThread, QUrl, Signal
from PySide6.QtGui import QGuiApplication, QTextDocument
from PySide6.QtGui import QKeySequence, QShortcut
from PySide6.QtWidgets import (QComboBox, QDialog, QHBoxLayout, QLabel, QPushButton, QTextBrowser, QVBoxLayout,
                               QWidget)

from ui.answer_view import DiagramZoomDialog, highlight_code_to_html, render_svg_to_pixmap
from ui.diagram_renderer import DiagramResult
from ui.privacy import set_window_capture_exclusion

BTN = ("QPushButton{background:#f1f5f9;color:#0f172a;font-weight:600;padding:5px 10px;border-radius:5px;"
       "border:1px solid #cbd5e1;font-size:12px;} QPushButton:hover{background:#e2e8f0;}"
       "QPushButton:disabled{color:#94a3b8;}")
PRIMARY = ("QPushButton{background:#b45309;color:#fff;font-weight:700;padding:5px 12px;border-radius:5px;"
           "border:none;font-size:12px;} QPushButton:hover{background:#92400e;} QPushButton:disabled{background:#d6d3d1;}")
STATUS_BADGE = {"supported": ("Supported", "#047857", "#d1fae5"), "partial": ("Partial", "#92400e", "#fef3c7"),
                "not_found": ("Not on file", "#b91c1c", "#fee2e2")}


class _Worker(QObject):
    done = Signal(dict)
    failed = Signal(str)

    def __init__(self, api, meeting_id):
        super().__init__()
        self.api, self.meeting_id = api, meeting_id

    def run(self):
        try:
            self.done.emit(self.api.generate_demo_prep(self.meeting_id))
        except Exception as exc:  # noqa: BLE001
            self.failed.emit(str(exc))


def prep_to_text(p: dict) -> str:
    out = ["INTRODUCTION", p.get("introduction_spoken", ""), ""]
    bm = p.get("best_match_project") or {}
    if bm:
        out += [f"Q: {bm.get('question')}", bm.get("spoken_answer", ""), ""]
    out.append("EXPERIENCE")
    out += [f"- {r.get('role')}: {r.get('spoken_answer')}" for r in p.get("experience_walkthrough", [])]
    out += ["", "LIKELY QUESTIONS"]
    for q in p.get("likely_questions", []):
        out += [f"Q: {q.get('question')}", f"A: {q.get('spoken_answer')}", ""]
    return "\n".join(out)


def _ul(items, cls: str = "") -> str:
    c = f" class='{cls}'" if cls else ""
    return "<ul>" + "".join(f"<li{c}>{escape(str(x))}</li>" for x in items or []) + "</ul>"


def prep_to_html(p: dict) -> str:
    e = lambda s: escape(str(s or ""))  # noqa: E731
    h = ["<style>h3{color:#1e3a8a;margin:16px 0 4px;} li{margin:2px 0;} .q{font-weight:700;color:#0f172a;}"
         ".muted{color:#64748b;} .gap{color:#b91c1c;} .ev{color:#047857;} p{margin:4px 0;}"
         ".say{background:#f8fafc;border-left:3px solid #2563eb;padding:6px 8px;}</style>"]
    h.append(f"<h3>1. Spoken introduction</h3><p class='say'>{e(p.get('introduction_spoken'))}</p>")
    bm = p.get("best_match_project") or {}
    if bm:
        h.append(f"<h3>2. \u201c{e(bm.get('question'))}\u201d</h3><p class='say'>{e(bm.get('spoken_answer'))}</p>"
                 + _ul(bm.get("highlights"))
                 + (f"<p class='muted'>Source: {e(bm.get('source'))}</p>" if bm.get("source") else ""))
    if p.get("experience_walkthrough"):
        h.append("<h3>3. Experience walkthrough \u2014 every role</h3>")
        for r in p["experience_walkthrough"]:
            jd = " \u00b7 ".join(r.get("jd_match") or [])
            h.append(f"<p class='q'>{e(r.get('role'))}</p><p class='say'>{e(r.get('spoken_answer'))}</p>"
                     + _ul(r.get("highlights")) + (f"<p class='ev'>Matches JD: {e(jd)}</p>" if jd else ""))
    if p.get("projects"):
        h.append("<h3>4. Projects on your CV</h3>")
        for pr in p["projects"]:
            h.append(f"<p class='q'>{e(pr.get('title'))}</p><p class='say'>{e(pr.get('spoken_answer'))}</p>"
                     + (f"<p class='ev'>JD relevance: {e(pr.get('jd_relevance'))}</p>" if pr.get("jd_relevance") else ""))
            for d in (pr.get("diagrams") or ([pr["diagram"]] if pr.get("diagram") else [])):
                if d.get("ok"):
                    lab = f"[{e(d.get('status'))}] {e(d.get('title'))}" if d.get("status") else "AWS flow diagram"
                    h.append(f"<p class='q'>{lab}</p><p><img src='prep-diagram-{d.get('index', 0)}' width='860'></p>")
            if pr.get("aws_flow"):
                h.append("<p class='q'>AWS flow</p><ol>" + "".join(f"<li>{e(x)}</li>" for x in pr["aws_flow"]) + "</ol>")
            if pr.get("system_design"):
                h.append(f"<p class='q'>System design</p><p class='say'>{e(pr['system_design'])}</p>")
            dbd = pr.get("database_design") or {}
            if dbd.get("spoken"):
                h.append(f"<p class='q'>Database design</p><p class='say'>{e(dbd['spoken'])}</p>"
                         + (_ul(dbd.get("tables")) if dbd.get("tables") else ""))
    if p.get("jd_alignment"):
        rows = []
        for a in p["jd_alignment"]:
            rows.append("<tr><td style='padding:4px'>"
                        f"<b>{e(a.get('requirement'))}</b>"
                        + (f"<br><span class='ev'>{e(a.get('evidence'))}</span>" if a.get("evidence") else "")
                        + (f"<br>\U0001f5e3 {e(a.get('how_to_talk_about_it'))}" if a.get("how_to_talk_about_it") else "")
                        + "</td></tr>")
        h.append("<h3>5. JD requirement \u2192 your evidence \u2192 how to talk about it</h3>"
                 "<table width='100%' cellspacing='0'>" + "".join(rows) + "</table>")
    arch = p.get("proposed_architecture") or {}
    if arch:
        h.append(f"<h3>6. PROPOSED: {e(arch.get('title'))}</h3><p class='say'>{e(arch.get('spoken_summary'))}</p>")
        if (arch.get("diagram") or {}).get("ok"):
            h.append("<p><img src='prep-diagram-0' width='860'></p>")
        elif arch.get("mermaid"):
            h.append(f"<pre>{e(arch.get('mermaid'))}</pre>")
        if arch.get("how_to_explain"):
            h.append("<p class='q'>How to explain it</p><ol>"
                     + "".join(f"<li>{e(x)}</li>" for x in arch["how_to_explain"]) + "</ol>")
        if arch.get("assumptions"):
            h.append("<p class='q'>Assumptions to state</p>" + _ul(arch["assumptions"]))
    db = p.get("proposed_database_model") or {}
    if db:
        h.append(f"<h3>7. PROPOSED SCHEMA: {e(db.get('title'))}</h3><p class='say'>{e(db.get('spoken_summary'))}</p>")
        if (db.get("diagram") or {}).get("ok"):
            h.append("<p><img src='prep-diagram-1' width='860'></p>")
        elif db.get("mermaid"):
            h.append(f"<pre>{e(db.get('mermaid'))}</pre>")
        if db.get("ddl"):
            h.append(highlight_code_to_html(db["ddl"]))
    ex = p.get("example_code") or {}
    if ex.get("code"):
        h.append(f"<h3>8. EXAMPLE CODE: {e(ex.get('title'))}</h3><p class='say'>{e(ex.get('explanation'))}</p>"
                 + highlight_code_to_html(ex["code"]))
    if p.get("likely_questions"):
        h.append("<h3>9. Likely client questions \u2014 read-aloud answers</h3>")
        for i, q in enumerate(p["likely_questions"], 1):
            h.append(f"<p class='q'>Q{i}. {e(q.get('question'))}</p><p class='say'>{e(q.get('spoken_answer'))}</p>"
                     + (f"<p class='ev'>Based on: {e(q.get('evidence'))}</p>" if q.get("evidence") else "")
                     + (f"<p class='muted'>Tip: {e(q.get('gap'))}</p>" if q.get("gap") else ""))
    if p.get("prepared_topics"):
        h.append("<h3>10. Prepared topics — read-aloud answers</h3>")
        for t in p["prepared_topics"]:
            h.append(f"<p class='q'>{e(t.get('question') or t.get('topic'))}</p><p class='say'>{e(t.get('spoken_answer'))}</p>"
                     + ("<ol>" + "".join(f"<li>{e(x)}</li>" for x in t["how_to_explain"]) + "</ol>"
                        if t.get("how_to_explain") else ""))
    return "".join(h)


def step_to_html(step: dict, total: int) -> str:
    e = lambda s: escape(str(s or ""))  # noqa: E731
    h = ["<style>.k{color:#0f766e;font-weight:700;font-size:12px;letter-spacing:1px;}"
         "h2{color:#0f172a;margin:4px 0 10px;font-size:21px;}"
         ".say{font-size:19px;line-height:135%;color:#0f172a;border-left:4px solid #0f766e;padding-left:12px;}"
         "li{font-size:15px;margin:3px 0;} .ex{background:#f0fdfa;border:1px solid #99f6e4;padding:8px;}"
         ".tip{color:#475569;font-size:13px;}</style>",
         f"<div class='k'>STEP {step.get('n')} OF {total} · {e(step.get('section')).upper()}</div>",
         f"<h2>{e(step.get('title'))}</h2>"]
    for para in str(step.get("say") or "").split("\n\n"):
        if para.strip():
            h.append(f"<p class='say'>{e(para)}</p>")
    if step.get("points"):
        h.append("<ul>" + "".join(f"<li>{e(x)}</li>" for x in step["points"]) + "</ul>")
    d = step.get("diagram") or {}
    if d.get("ok"):
        h.append(f"<p><img src='prep-diagram-{d.get('index', 0)}' width='820'></p>")
    if (step.get("code") or {}).get("code"):
        h.append(highlight_code_to_html(step["code"]["code"]))
    if step.get("explain"):
        h.append("<div class='ex'><b>How to explain it</b><ol>"
                 + "".join(f"<li>{e(x)}</li>" for x in step["explain"]) + "</ol></div>")
    if step.get("note"):
        h.append(f"<p class='tip'>Tip: {e(step['note'])}</p>")
    return "".join(h)


class DemoPrepDialog(QDialog):
    def __init__(self, api, meeting_id: str | None, parent: QWidget | None = None,
                 privacy_enabled: bool = True) -> None:
        super().__init__(parent)
        self.api, self.meeting_id, self._privacy = api, meeting_id, privacy_enabled
        self.data: dict = {}
        self._thread: QThread | None = None
        self.setWindowTitle("🎯 Demo Prep")
        self.setMinimumSize(760, 520)
        self.resize(1100, 700)

        root = QVBoxLayout(self)
        root.setContentsMargins(14, 12, 14, 12)
        self.banner = QLabel("Loading…")
        self.banner.setWordWrap(True)
        self.banner.setStyleSheet("background:#fef3c7;color:#92400e;font-size:12px;padding:8px 10px;"
                                  "border:1px solid #fcd34d;border-radius:6px;")
        root.addWidget(self.banner)

        self.view = QTextBrowser()
        self.view.setOpenLinks(False)
        self.view.setStyleSheet("QTextBrowser{background:#fff;border:1px solid #cbd5e1;border-radius:6px;"
                                "font-size:13px;padding:8px;}")
        root.addWidget(self.view, 1)

        self.step_row = QWidget()
        sr = QHBoxLayout(self.step_row)
        sr.setContentsMargins(0, 0, 0, 0)
        self.back_btn = QPushButton("◀  Back")
        self.next_btn = QPushButton("Next  ▶")
        self.copy_step_btn = QPushButton("Copy this step")
        self.step_combo = QComboBox()
        self.step_combo.setMinimumWidth(360)
        for b in (self.back_btn, self.copy_step_btn):
            b.setStyleSheet(BTN + "QPushButton{min-height:38px;font-size:14px;}")
        self.next_btn.setStyleSheet("QPushButton{background:#0f766e;color:#fff;font-weight:700;min-height:38px;"
                                    "padding:5px 18px;border-radius:6px;border:none;font-size:14px;}"
                                    "QPushButton:hover{background:#115e59;} QPushButton:disabled{background:#94a3b8;}")
        self.back_btn.clicked.connect(lambda: self._go(self._step - 1))
        self.next_btn.clicked.connect(lambda: self._go(self._step + 1))
        self.copy_step_btn.clicked.connect(self._copy_step)
        self.step_combo.currentIndexChanged.connect(lambda i: i >= 0 and i != self._step and self._go(i))
        self.step_zoom_btn = QPushButton("🔍 Zoom diagram")
        self.step_zoom_btn.setStyleSheet(BTN + "QPushButton{min-height:38px;font-size:14px;}")
        self.step_zoom_btn.setEnabled(False)
        self.step_zoom_btn.clicked.connect(self._zoom_step)
        self._all_diagrams = {}
        sr.addWidget(self.back_btn)
        sr.addWidget(self.step_combo, 1)
        sr.addWidget(self.step_zoom_btn)
        sr.addWidget(self.copy_step_btn)
        sr.addWidget(self.next_btn)
        root.addWidget(self.step_row)
        self._step = 0
        self._script: list = []
        self._mode = "script"
        QShortcut(QKeySequence(Qt.Key.Key_Right), self, activated=lambda: self._mode == "script" and self._go(self._step + 1))
        QShortcut(QKeySequence(Qt.Key.Key_Left), self, activated=lambda: self._mode == "script" and self._go(self._step - 1))

        row = QHBoxLayout()
        self.gen_btn = QPushButton("✨ Generate from my documents")
        self.gen_btn.setStyleSheet(PRIMARY)
        self.gen_btn.clicked.connect(self._generate)
        row.addWidget(self.gen_btn)
        self.mode_btn = QPushButton("📄 Full view")
        self.mode_btn.setStyleSheet(BTN)
        self.mode_btn.clicked.connect(self._toggle_mode)
        row.addWidget(self.mode_btn)
        self.copy_intro_btn = QPushButton("📋 Copy introduction")
        self.copy_all_btn = QPushButton("📄 Copy all")
        for b in (self.copy_intro_btn, self.copy_all_btn):
            b.setStyleSheet(BTN)
            row.addWidget(b)
        self.copy_intro_btn.clicked.connect(lambda: self._copy(self.data.get("prep", {}).get("introduction_spoken", ""),
                                                               self.copy_intro_btn, "📋 Copy introduction"))
        self.copy_all_btn.clicked.connect(lambda: self._copy(prep_to_text(self.data.get("prep", {})),
                                                             self.copy_all_btn, "📄 Copy all"))
        self.zoom_btns = []
        for idx, label in ((0, "🔍 Architecture"), (1, "🔍 ER diagram")):
            zb = QPushButton(label)
            zb.setStyleSheet(BTN)
            zb.setEnabled(False)
            zb.clicked.connect(lambda _=False, i=idx: self._zoom(i))
            row.addWidget(zb)
            self.zoom_btns.append(zb)
        self._diagrams: list = []
        row.addStretch()
        close = QPushButton("Close")
        close.setStyleSheet(BTN)
        close.clicked.connect(self.accept)
        row.addWidget(close)
        root.addLayout(row)
        self._load()

    def showEvent(self, event) -> None:  # noqa: N802
        super().showEvent(event)
        if not getattr(self, '_maxed', False):
            self._maxed = True
            self.showMaximized()
        if self._privacy:
            set_window_capture_exclusion(int(self.winId()), True)

    def _copy(self, text: str, btn: QPushButton, label: str) -> None:
        QGuiApplication.clipboard().setText(text or "")
        btn.setText("✓ Copied")
        from PySide6.QtCore import QTimer
        QTimer.singleShot(1500, lambda: btn.setText(label))

    def _load(self) -> None:
        if self.api is None:
            self.banner.setText("Not connected to the backend.")
            return
        try:
            self._render(self.api.get_demo_prep(self.meeting_id))
        except Exception as exc:  # noqa: BLE001
            self.banner.setText(f"Could not load Demo Prep: {exc}")

    def _render(self, data: dict) -> None:
        self.data = data
        status = data.get("status")
        has = status in ("ready", "stale")
        self.copy_intro_btn.setEnabled(has)
        self.copy_all_btn.setEnabled(has)
        docs = data.get("documents") or []
        names = ", ".join(f"{d['filename']} ({d['doc_type']})" for d in docs) or "no documents"
        if status == "not_generated":
            cur = data.get("documents") or []
            self.banner.setText("No Demo Prep generated yet. It will be built only from: "
                                + (", ".join(d["filename"] for d in cur) or "— upload a CV and JD first"))
            self.view.setHtml("<p style='color:#64748b'>Click <b>Generate from my documents</b>. "
                              "Nothing here is pre-written; every point comes from your selected documents, "
                              "and anything not supported is listed as a gap.</p>")
            self.gen_btn.setText("✨ Generate from my documents")
            return
        when = data.get("generated_at", "")
        try:
            when = datetime.fromisoformat(when).astimezone().strftime("%d %b %Y %H:%M")
        except ValueError:
            pass
        msg = f"Generated {when} with {data.get('model')} from: {names}."
        if status == "stale":
            msg = "⚠ Your selected documents changed since this was generated — regenerate. " + msg
        prep = data.get("prep", {})
        if not (prep.get("introduction_spoken") or prep.get("experience_walkthrough")):
            self.banner.setText("This Demo Prep uses the older format — click Regenerate to build the full pack.")
            self.view.setHtml("<p style='color:#64748b'>Click <b>Regenerate</b>.</p>")
            self.copy_intro_btn.setEnabled(False)
            self.copy_all_btn.setEnabled(False)
            self.gen_btn.setText("🔄 Regenerate")
            return
        short = ("⚠ Documents changed since this was generated — Demo Prep is still usable." if status == "stale"
                 else f"Generated {when} with {data.get('model')}.")
        self.banner.setText(short)
        self.banner.setToolTip(msg)
        self._diagrams = []
        for i, key in enumerate(("proposed_architecture", "proposed_database_model")):
            d = (prep.get(key) or {}).get("diagram") or {}
            res = (DiagramResult(d.get("index", i), d.get("kind", "unknown"), d.get("source", ""), d.get("svg"),
                                 bool(d.get("ok")), d.get("error")) if d else None)
            self._diagrams.append(res)
            self.zoom_btns[i].setEnabled(bool(res and res.ok))
            if res and res.ok and res.svg:
                self.view.document().addResource(QTextDocument.ResourceType.ImageResource, QUrl(f"prep-diagram-{i}"),
                                                 render_svg_to_pixmap(res.svg, target_width=860).toImage())
        self._all_diagrams = {}
        seen = []
        for pr in prep.get("projects") or []:
            seen += (pr.get("diagrams") or ([pr["diagram"]] if pr.get("diagram") else []))
        seen += [s["diagram"] for s in (data.get("script") or []) if s.get("diagram")]
        for d in seen:
            if not d or not d.get("ok") or not d.get("svg") or d.get("index") in self._all_diagrams:
                continue
            idx = d.get("index", 0)
            self._all_diagrams[idx] = DiagramResult(idx, d.get("kind", "unknown"), d.get("source", ""), d.get("svg"),
                                                    True, d.get("error"))
            self.view.document().addResource(QTextDocument.ResourceType.ImageResource, QUrl(f"prep-diagram-{idx}"),
                                             render_svg_to_pixmap(d["svg"], target_width=860).toImage())
        self._script = data.get("script") or []
        self.step_combo.blockSignals(True)
        self.step_combo.clear()
        for st in self._script:
            self.step_combo.addItem(f"{st.get('n')}. {st.get('section')} — {str(st.get('title') or '')[:70]}")
        self.step_combo.blockSignals(False)
        self._full_html = prep_to_html(prep)
        self._apply_mode()
        self.gen_btn.setText("🔄 Regenerate")

    def _apply_mode(self) -> None:
        script = self._mode == "script" and bool(self._script)
        self.step_row.setVisible(script)
        self.mode_btn.setText("📄 Full view" if script else "🎙 Script")
        if script:
            self._go(min(self._step, len(self._script) - 1))
        else:
            self.view.setHtml(getattr(self, "_full_html", ""))

    def _toggle_mode(self) -> None:
        self._mode = "full" if self._mode == "script" else "script"
        self._apply_mode()

    def _go(self, i: int) -> None:
        if not self._script:
            return
        self._step = max(0, min(len(self._script) - 1, i))
        self.view.setHtml(step_to_html(self._script[self._step], len(self._script)))
        self.back_btn.setEnabled(self._step > 0)
        self.next_btn.setEnabled(self._step < len(self._script) - 1)
        self.step_combo.blockSignals(True)
        self.step_combo.setCurrentIndex(self._step)
        self.step_combo.blockSignals(False)
        self.copy_step_btn.setText("Copy this step")
        sd = self._script[self._step].get("diagram") or {}
        self.step_zoom_btn.setEnabled(bool(sd.get("ok") and sd.get("index") in self._all_diagrams))

    def _zoom_step(self) -> None:
        sd = (self._script[self._step].get("diagram") or {}) if self._script else {}
        d = self._all_diagrams.get(sd.get("index"))
        if d and d.ok:
            dlg = DiagramZoomDialog(d, self)
            if self._privacy:
                dlg.show()
                set_window_capture_exclusion(int(dlg.winId()), True)
            dlg.exec()

    def _copy_step(self) -> None:
        if self._script:
            st = self._script[self._step]
            text = "\n".join([st.get("say") or ""] + [f"• {p}" for p in st.get("points") or []])
            self._copy(text, self.copy_step_btn, "Copy this step")

    def _zoom(self, i: int) -> None:
        d = self._diagrams[i] if i < len(self._diagrams) else None
        if d and d.ok:
            dlg = DiagramZoomDialog(d, self)
            if self._privacy:
                dlg.show()
                set_window_capture_exclusion(int(dlg.winId()), True)
            dlg.exec()

    def _generate(self) -> None:
        if self.api is None or (self._thread and self._thread.isRunning()):
            return
        self.gen_btn.setEnabled(False)
        self.gen_btn.setText("Generating… (~1–2 min)")
        self._thread = QThread(self)
        self._worker = _Worker(self.api, self.meeting_id)
        self._worker.moveToThread(self._thread)
        self._thread.started.connect(self._worker.run)
        self._worker.done.connect(self._on_done)
        self._worker.failed.connect(self._on_failed)
        self._worker.done.connect(self._thread.quit)
        self._worker.failed.connect(self._thread.quit)
        self._thread.start()

    def _on_done(self, data: dict) -> None:
        self.gen_btn.setEnabled(True)
        self._render(data)

    def _on_failed(self, message: str) -> None:
        self.gen_btn.setEnabled(True)
        self.gen_btn.setText("✨ Generate from my documents")
        self.banner.setText(f"Generation failed: {message}")

    def closeEvent(self, event) -> None:  # noqa: N802
        if self._thread and self._thread.isRunning():
            self._thread.quit()
            self._thread.wait(200)
        super().closeEvent(event)
